  (1, 'Jennings Media', 'Real estate media that sells the property.', 'hello@jenningsmedia.com', null, 'Tampa', 'FL', 'US', 27.9506, -82.4572, 'America/New_York', 'usd', 0, 'Sales tax', false, '{"allow_full":true,"allow_deposit":true,"allow_pay_later":true,"deposit_type":"percent","deposit_value":30,"pay_later_note":"Pay securely online once your media is ready — before download."}'::jsonb, '{"working_hours":{"0":[],"1":[{"start":"08:00","end":"18:00"}],"2":[{"start":"08:00","end":"18:00"}],"3":[{"start":"08:00","end":"18:00"}],"4":[{"start":"08:00","end":"18:00"}],"5":[{"start":"08:00","end":"18:00"}],"6":[{"start":"09:00","end":"16:00"}]},"slot_interval_minutes":30,"max_shoots_per_day":6,"travel_buffer_minutes":30,"default_duration_minutes":60,"min_notice_hours":18,"max_advance_days":60,"hold_minutes":35,"twilight_lead_minutes":25}'::jsonb, '{"enabled":true,"referrer_reward_cents":5000,"referee_discount_type":"fixed","referee_discount_value":2500,"qualify_on":"paid"}'::jsonb, '{"admin_emails":[],"reminder_hours_before":24,"sms_enabled":false,"reply_to":""}'::jsonb, '{"ga4_id":"","meta_pixel_id":"","google_ads_id":"","google_ads_booking_label":""}'::jsonb, '{"instagram":"","facebook":"","youtube":"","tiktok":"","linkedin":""}'::jsonb, '{"outside_area_policy":"quote","outside_area_fee_cents":7500,"road_distance_factor":1.25}'::jsonb)
insert into public.services (id, slug, name, category, tagline, description, features, icon, image_url, gallery, pricing_model, base_price_cents, price_tiers, unit_label, max_quantity, duration_minutes, turnaround_hours, scheduling_rules, is_bookable, is_addon_eligible, is_featured, is_active, sort_order) values
  ('5e000000-0000-4000-8000-000000000001', 'photography', 'Professional Photography', 'photography', 'Bright, true-to-life HDR photos, hand-edited and delivered the next morning.', 'Every room is bracketed, blended and edited by hand for balanced windows, straight verticals and accurate color. You get MLS-sized and print-ready files, organized in the order buyers walk the home.', array['25–60 hand-edited HDR images', 'Window pulls, sky replacement & color correction', 'MLS-ready and full-resolution print files', 'Delivered by 9 AM the next morning']::text[], 'camera', 'https://images.unsplash.com/photo-1600585154526-990dced4db0d?auto=format&fit=crop&w=2000&q=80', '[{"url":"https://images.unsplash.com/photo-1600121848594-d8644e57abab?auto=format&fit=crop&w=2000&q=80","alt":"Bright modern kitchen"},{"url":"https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=2000&q=80","alt":"Primary suite"},{"url":"https://images.unsplash.com/photo-1600566752355-35792bedcfea?auto=format&fit=crop&w=2000&q=80","alt":"Marble bathroom"}]'::jsonb, 'sqft', 17500, '[{"max_sqft":1500,"price_cents":17500},{"max_sqft":2500,"price_cents":19900},{"max_sqft":3500,"price_cents":23900},{"max_sqft":5000,"price_cents":28900},{"max_sqft":null,"price_cents":34900}]'::jsonb, null, null, 75, 24, '{}'::jsonb, true, true, true, true, 10),
  ('5e000000-0000-4000-8000-000000000002', 'drone-photography', 'Drone Photography', 'drone', 'FAA Part 107 aerials that show the lot, the views and the neighborhood.', 'Elevated and high-altitude angles reveal what ground photos can''t: lot size, water and golf views, proximity to amenities. Optional lot-line overlays on request.', array['10–15 aerial images', 'Licensed & insured pilots', 'Lot-line overlays available', 'Neighborhood context shots']::text[], 'plane', 'https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=2000&q=80', '[{"url":"https://images.unsplash.com/photo-1524813686514-a57563d77965?auto=format&fit=crop&w=2000&q=80","alt":"Coastal aerial"}]'::jsonb, 'flat', 12500, '[]'::jsonb, null, null, 20, 24, '{"daylight_only":true,"requires_skill":"drone"}'::jsonb, true, true, true, true, 20),
  ('5e000000-0000-4000-8000-000000000003', 'drone-video', 'Drone Video', 'drone', 'Sweeping 4K aerial footage cut into a 60–90 second film.', 'Smooth reveals, orbits and fly-throughs of the property and surrounding area, color graded and edited to licensed music. Branded and unbranded (MLS) versions included.', array['60–90 second edit', '4K, color graded', 'Licensed music', 'Branded + MLS-unbranded versions']::text[], 'clapperboard', 'https://images.unsplash.com/photo-1473968512647-3e447244af8f?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'flat', 19900, '[]'::jsonb, null, null, 25, 48, '{"daylight_only":true,"requires_skill":"drone"}'::jsonb, true, true, false, true, 30),
  ('5e000000-0000-4000-8000-000000000004', 'cinematic-video', 'Cinematic Property Video', 'video', 'A gimbal-shot listing film with story, motion and music.', 'A 1–2 minute film shot in 4K on a stabilized gimbal, sequenced like a showing and finished with color grading and licensed music. Optional agent intro on camera.', array['1–2 minute 4K film', 'Gimbal-stabilized motion', 'Color grading & licensed music', 'Optional agent on-camera intro']::text[], 'film', 'https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'sqft', 34900, '[{"max_sqft":2500,"price_cents":34900},{"max_sqft":4000,"price_cents":42500},{"max_sqft":null,"price_cents":52500}]'::jsonb, null, null, 60, 48, '{"requires_skill":"video"}'::jsonb, true, true, true, true, 40),
  ('5e000000-0000-4000-8000-000000000005', 'social-media-reel', 'Vertical Realtor Reel', 'video', 'A scroll-stopping 9:16 reel for Instagram, TikTok and Shorts.', 'Fast-paced vertical edits built for social: hook in the first second, captions, trending-style pacing and an optional agent cameo.', array['30–60 second 9:16 edit', 'On-screen captions', 'Hook-first pacing', 'Ready to post']::text[], 'smartphone', 'https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'flat', 19900, '[]'::jsonb, null, null, 30, 48, '{"requires_skill":"video"}'::jsonb, true, true, true, true, 50),
  ('5e000000-0000-4000-8000-000000000006', 'matterport-3d-tour', 'Matterport 3D Tour', 'tour', 'An immersive walkthrough buyers can explore from anywhere, 24/7.', 'A Matterport Pro scan with dollhouse view, floor-plan view and measurement mode. Branded and MLS-compliant unbranded links, hosted for six months.', array['Dollhouse & floor-plan views', 'Branded + unbranded links', 'Embeddable anywhere', 'Hosted for 6 months']::text[], 'box', 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'sqft', 19900, '[{"max_sqft":2000,"price_cents":19900},{"max_sqft":3500,"price_cents":24900},{"max_sqft":5000,"price_cents":29900},{"max_sqft":null,"price_cents":37900}]'::jsonb, null, null, 60, 48, '{"min_notice_hours":24,"requires_skill":"tour"}'::jsonb, true, true, true, true, 60),
  ('5e000000-0000-4000-8000-000000000007', 'floor-plans', 'Floor Plans', 'floor_plan', 'Accurate 2D plans with room dimensions and total square footage.', 'Laser-measured floor plans drawn to scale, with room names, dimensions and total living area. Delivered as high-resolution PNG and PDF.', array['Laser-measured', 'Room dimensions & totals', 'PNG + PDF', 'Branded or unbranded']::text[], 'ruler', 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'sqft', 8900, '[{"max_sqft":2000,"price_cents":8900},{"max_sqft":3500,"price_cents":11900},{"max_sqft":null,"price_cents":14900}]'::jsonb, null, null, 20, 24, '{}'::jsonb, true, true, true, true, 70),
  ('5e000000-0000-4000-8000-000000000008', 'virtual-twilight', 'Virtual Twilight', 'editing', 'Turn a daytime exterior into a glowing golden-hour hero shot.', 'Our editors convert daytime exteriors into realistic dusk scenes: warm interior glow, dramatic sky and landscape lighting — without a second visit.', array['Realistic dusk sky', 'Warm window glow', 'No return visit needed', 'Delivered with your photos']::text[], 'sunset', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'per_unit', 3500, '[]'::jsonb, 'image', 10, 0, 24, '{}'::jsonb, true, true, true, true, 80),
  ('5e000000-0000-4000-8000-000000000009', 'twilight-photography', 'Twilight Photography', 'photography', 'An on-site golden-hour session when the home looks its best.', 'We arrive before sunset and capture the exterior (and key interiors) as the sky turns deep blue and the home glows. Scheduled automatically around the day''s sunset.', array['Scheduled around sunset', '8–12 twilight images', 'Exterior & key interiors', 'Weather-guaranteed reschedule']::text[], 'moon', 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'flat', 24900, '[]'::jsonb, null, null, 45, 24, '{"twilight":true}'::jsonb, true, true, false, true, 90),
  ('5e000000-0000-4000-8000-000000000010', 'property-website', 'Property Website', 'web', 'A beautiful single-property site with gallery, video, tour and lead capture.', 'A mobile-first listing website generated from your delivered media, with a shareable link, QR code for signage and an unbranded version for the MLS.', array['Gallery, video & 3D tour', 'Shareable link + QR code', 'Branded & unbranded', 'Live within 24 hours']::text[], 'globe', 'https://images.unsplash.com/photo-1600047509807-ba8f99d2cdde?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'flat', 7900, '[]'::jsonb, null, null, 0, 24, '{}'::jsonb, true, true, true, true, 100),
  ('5e000000-0000-4000-8000-000000000011', 'marketing-kit', 'Marketing Kit', 'marketing', 'Flyers, social graphics and ‘Just Listed’ posts, ready to share.', 'A designed launch kit built from your listing media: print flyer, feature sheet, Instagram carousel and story graphics, plus ‘Just Listed’ and ‘Under Contract’ posts.', array['Print flyer & feature sheet', 'Social carousel & stories', 'Just Listed / Sold posts', 'Editable templates']::text[], 'layout-template', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'flat', 9900, '[]'::jsonb, null, null, 0, 48, '{}'::jsonb, true, true, true, true, 110),
  ('5e000000-0000-4000-8000-000000000012', 'agent-branding', 'Agent Branding Content', 'branding', 'Headshots and personal-brand video that make you instantly recognizable.', 'Studio-quality headshots, lifestyle portraits and short intro videos for your website, listings and social channels. Custom-quoted for individuals and teams.', array['Headshots & lifestyle portraits', 'Intro & about-me videos', 'Team sessions', 'Custom quote']::text[], 'user-round', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=2000&q=80', '[]'::jsonb, 'flat', 34900, '[]'::jsonb, null, null, 90, 72, '{}'::jsonb, false, false, false, true, 120)
