  ('9a000000-0000-4000-8000-000000000001', 'essential', 'Essential', 'Everything a listing needs to go live tomorrow.', 'Professional listing photography and a clean floor plan — the essentials, done beautifully.', array['Professional listing photography', 'Basic 2D floor plan', 'Next-day delivery', 'MLS-ready sizing']::text[], 25000, '[{"max_sqft":2500,"price_cents":25000},{"max_sqft":3500,"price_cents":29500},{"max_sqft":5000,"price_cents":34500},{"max_sqft":null,"price_cents":42500}]'::jsonb, null, 'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=2000&q=80', 'Next-day delivery', false, true, 10),
  ('9a000000-0000-4000-8000-000000000002', 'pro', 'Pro', 'Photos, aerials and a full marketing launch in one visit.', 'Our most-booked package: ground and aerial photography, a floor plan, a property website and a ready-to-post marketing kit.', array['Professional photography', 'Drone photography', 'Floor plan', 'Property website', 'Marketing kit']::text[], 45000, '[{"max_sqft":2500,"price_cents":45000},{"max_sqft":3500,"price_cents":51500},{"max_sqft":5000,"price_cents":59500},{"max_sqft":null,"price_cents":72500}]'::jsonb, 'Most popular', 'https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=2000&q=80', 'Photos next day · kit in 48h', true, true, 20),
  ('9a000000-0000-4000-8000-000000000003', 'signature', 'Signature', 'The cinematic launch for listings that deserve a premiere.', 'Everything in Pro plus a cinematic property film and a vertical reel built for social reach.', array['Professional photography', 'Drone photography', 'Cinematic property video', 'Vertical social media reel', 'Floor plan', 'Property website', 'Marketing kit']::text[], 65000, '[{"max_sqft":2500,"price_cents":65000},{"max_sqft":3500,"price_cents":75000},{"max_sqft":5000,"price_cents":87500},{"max_sqft":null,"price_cents":105000}]'::jsonb, 'Best value', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=2000&q=80', 'Photos next day · film in 48h', false, true, 30)
