insert into public.portfolio_projects (id, slug, title, neighborhood, property_type, categories, description, services_performed, cover_image_url, is_featured, is_published, is_sample, sort_order) values
  ('90000000-0000-4000-8000-000000000001', 'bayfront-modern', 'Bayfront Modern', 'Waterfront', 'Luxury single-family', array['photography', 'twilight', 'luxury', 'residential']::text[], 'A glass-walled waterfront home captured at dusk to show off its pool terrace and open-plan interiors.', array['Photography', 'Twilight Photography', 'Drone Photography']::text[], 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=2400&q=80', true, true, true, 10),
  ('90000000-0000-4000-8000-000000000002', 'palm-ridge-estate', 'Palm Ridge Estate', 'Golf community', 'Estate', array['luxury', 'drone', 'video', 'residential']::text[], 'Aerial reveals and a cinematic walkthrough for a resort-style estate with a pool pavilion.', array['Cinematic Video', 'Drone Video', 'Photography']::text[], 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=2400&q=80', true, true, true, 20),
  ('90000000-0000-4000-8000-000000000003', 'island-twilight', 'Island Twilight', 'Island district', 'Single-family', array['twilight', 'photography', 'luxury']::text[], 'A golden-hour session timed to the minute for a glowing exterior and warm interiors.', array['Twilight Photography', 'Virtual Twilight']::text[], 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=2000&q=80', true, true, true, 30),
  ('90000000-0000-4000-8000-000000000004', 'harbor-view-residence', 'Harbor View Residence', 'Downtown', 'Condo', array['photography', 'residential']::text[], 'Bright, airy condo photography that makes a 1,400 sq ft floor plan feel expansive.', array['Photography', 'Floor Plan', 'Matterport 3D Tour']::text[], 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=2000&q=80', false, true, true, 40),
  ('90000000-0000-4000-8000-000000000005', 'coastal-aerial-series', 'Coastal Aerial Series', 'Gulf coast', 'Land & lots', array['drone', 'residential']::text[], 'High-altitude drone stills showing water access, lot lines and neighborhood amenities.', array['Drone Photography', 'Drone Video']::text[], 'https://images.unsplash.com/photo-1524813686514-a57563d77965?auto=format&fit=crop&w=2000&q=80', true, true, true, 50),
  ('90000000-0000-4000-8000-000000000006', 'midtown-office-suites', 'Midtown Office Suites', 'Business district', 'Commercial office', array['commercial', 'photography']::text[], 'Leasing photography for a boutique office building — lobby, suites and amenity spaces.', array['Photography', 'Matterport 3D Tour']::text[], 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=2000&q=80', false, true, true, 60),
