insert into public.testimonials (id, author_name, author_title, company, quote, rating, is_featured, is_published, is_sample, sort_order) values
  ('7e000000-0000-4000-8000-000000000001', 'Alexis M.', 'Listing Agent', null, 'Booked at 10 PM, shot the next morning, photos in my inbox before my first coffee the day after. The listing had 14 showings the first weekend.', 5, true, true, true, 10),
  ('7e000000-0000-4000-8000-000000000002', 'Jordan T.', 'Broker Associate', null, 'The twilight shots made our listing the first thing people saw on the portal. Clients ask who our photographer is every single time.', 5, true, true, true, 20),
  ('7e000000-0000-4000-8000-000000000003', 'Priya S.', 'Property Manager', null, 'We run 40+ rentals. One dashboard for every property, invoices in one place, media I can download in one click. It just works.', 5, true, true, true, 30),
  ('7e000000-0000-4000-8000-000000000004', 'Marcus L.', 'Real Estate Investor', null, 'The cinematic video and reel did more for our flip than any open house. Professional, on time, zero back-and-forth.', 5, true, true, true, 40),
  ('7e000000-0000-4000-8000-000000000005', 'Dana R.', 'Short-term Rental Host', null, 'Our booking rate jumped after the new photos went live. The drone shots of the beach access sold the place for us.', 5, true, true, true, 50),
  ('7e000000-0000-4000-8000-000000000006', 'Chris W.', 'Team Lead', null, 'Our whole team books through the site now. Consistent quality on every listing means our brand finally looks as good as our service.', 5, true, true, true, 60)
